                merged.back().second = max(merged.back().second, intervals[i].second);
            } else {
                merged.push_back(intervals[i]);
            }
        }

        for (auto& interval : merged) {
            cout << interval.first << " " << interval.second << endl;
        }
    }
    return 0;
